<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Oidc\Scopes\Infrastructure\Driven;

use Override;
use Civi\Lughauth\Shared\Observability\LoggerAwareTrait;
use Civi\Lughauth\Features\Access\Tenant\Domain\Gateway\TenantReadGateway;
use Civi\Lughauth\Features\Access\User\Domain\Gateway\UserReadGateway;
use Civi\Lughauth\Features\Access\User\Domain\UserRef;
use Civi\Lughauth\Features\Access\TrustedClient\Domain\Gateway\TrustedClientReadGateway;
use Civi\Lughauth\Features\Access\TrustedClient\Domain\TrustedClientRef;
use Civi\Lughauth\Features\Oidc\Scopes\Infrastructure\Service\UserConsentedScopeGrant;
use Civi\Lughauth\Features\Oidc\Scopes\Infrastructure\Service\UserConsentedScopePending;
use Civi\Lughauth\Features\Oidc\Scopes\Infrastructure\Service\UserConsentedScopeRevoke;
use Civi\Lughauth\Features\Oidc\Scopes\Domain\Gateway\ScopesConsentGateway;
use Civi\Lughauth\Features\Oidc\Scopes\Domain\ScopePermission;

class ScopesConsentAdapter implements ScopesConsentGateway
{
    use LoggerAwareTrait;

    public function __construct(
        private readonly TenantReadGateway $tenants,
        private readonly UserReadGateway $users,
        private readonly TrustedClientReadGateway $clients,
        private readonly UserConsentedScopeGrant $grantUsecase,
        private readonly UserConsentedScopePending $pendingUsecase,
        private readonly UserConsentedScopeRevoke $revokeUsecase,
    ) {
    }

    /**
     * @param string[] $scopes
     *
     * @return ScopePermission[]
     */
    #[Override]
    public function pendingScopes(string $tenant, string $username, string $clientId, array $scopes): array
    {
        $user = $this->resolveUser($tenant, $username);
        $client = $this->resolveClient($clientId);

        if (null === $user || null === $client) {
            // Cannot resolve identities — conservatively treat all scopes as pending
            return array_map(
                static fn (string $scope): ScopePermission => new ScopePermission(scope: $scope, required: false),
                $scopes
            );
        }

        $pending = $this->pendingUsecase->pending($user, $client, $scopes);

        return array_map(
            static fn (string $scope): ScopePermission => new ScopePermission(scope: $scope, required: false),
            $pending
        );
    }

    /**
     * @param string[] $scopes
     */
    #[Override]
    public function storeAcceptedScopes(string $tenant, string $username, string $clientId, array $scopes): void
    {
        $user = $this->resolveUser($tenant, $username);
        $client = $this->resolveClient($clientId);

        if (null === $user || null === $client) {
            $this->logWarning("ScopesConsentAdapter: could not resolve user or client — consent not stored", [
                'tenant' => $tenant,
                'username' => $username,
                'clientId' => $clientId,
            ]);
            return;
        }

        $this->grantUsecase->grant($user, $client, $scopes);
    }

    private function resolveUser(string $tenant, string $username): ?UserRef
    {
        // Session-based flows set username to the user UID; try that first
        $byUid = $this->users->findOneByUid($username);
        if (null !== $byUid) {
            return $byUid;
        }

        // $tenant is the tenant slug/name — resolve it to get the actual tenant entity
        $resolvedTenant = $this->tenants->findOneByName($tenant);
        if (null === $resolvedTenant) {
            return null;
        }

        // Standard login flow: username is the login name within the tenant
        return $this->users->findOneByTenantAndName($resolvedTenant, $username);
    }

    private function resolveClient(string $clientId): ?TrustedClientRef
    {
        return $this->clients->findOneByCode($clientId);
    }
}
